735	// Owner returns the owner portion of the repo field (before the slash).
736	// Returns empty string if the repo field doesn't contain a slash.
737	func (c *CheckpointRemoteConfig) Owner() string {
738		parts := strings.SplitN(c.Repo, "/", 2)
