746	// Expects a structured object: {"provider": "github", "repo": "org/repo"}.
747	// Returns nil if not configured, wrong type, or missing required fields.
748	func (s *EntireSettings) GetCheckpointRemote() *CheckpointRemoteConfig {
749		if s.StrategyOptions == nil {
750			return nil
751		}
752		val, ok := s.StrategyOptions["checkpoint_remote"]
753		if !ok {
754			return nil
755		}
756		m, ok := val.(map[string]any)
757		if !ok {
758			return nil
759		}
760		provider, providerOK := m["provider"].(string)
761		repo, repoOK := m["repo"].(string)
762		if !providerOK || !repoOK || provider == "" || repo == "" {
763			return nil
764		}
765		if !strings.Contains(repo, "/") {
766			return nil
767		}
768		return &CheckpointRemoteConfig{Provider: provider, Repo: repo}
