802	func parseCheckpointsVersion(val any) (int, bool) {
803		v, ok := val.(int)
804		if ok && (v == 1 || v == 2) {
805			return v, true
806		}
807		floatV, ok := val.(float64)
808		if ok && (floatV == 1 || floatV == 2) {
809			return int(floatV), true
810		}
811		stringV, ok := val.(string)
812		if ok {
813			parsed, err := strconv.Atoi(stringV)
814			if err == nil && (parsed == 1 || parsed == 2) {
815				return parsed, true
816			}
817		}
818		return 1, false
819	}
