38	// attachOptions carries optional flags for runAttach. Force is the original
39	// flag; Review opts the attach into recording the session as an
40	// agent_review in the checkpoint metadata.
41	type attachOptions struct {
42		Force bool
43		// Review, when true, tags the attached session as a review. Skills are
44		// resolved inside runAttach after the real agent is known (via session
45		// state or transcript auto-detection), not at the cobra layer — the
46		// --agent flag's default points at claude-code, which would otherwise
47		// make a Gemini session incorrectly look up review.claude-code config.
48		Review bool
49		// ReviewSkillsOverride, when non-empty, overrides the agent's
50		// configured review skills. Empty means "read review.<agent> from
51		// settings after resolving the real agent". Ignored when Review=false.
52		ReviewSkillsOverride []string
53	}
