124	// runAttachSurfaceReviewErrors wraps runAttach so review-mode errors reach
125	// the user as clear stderr messages rather than generic cobra error output.
126	// The non-review path preserves the existing runAttach return-err behavior.
127	func runAttachSurfaceReviewErrors(cmd *cobra.Command, sessionID string, agentName types.AgentName, opts attachOptions) error {
128		err := runAttach(cmd.Context(), cmd.OutOrStdout(), sessionID, agentName, opts)
129		if err != nil && opts.Review {
130			cmd.SilenceUsage = true
131			fmt.Fprintln(cmd.ErrOrStderr(), err.Error())
132			return NewSilentError(err)
133		}
134		return err
135	}
