137	func runAttach(ctx context.Context, w io.Writer, sessionID string, agentName types.AgentName, opts attachOptions) error {
138		// Initialize structured logger so logging.Warn/Info write to .entire/logs/ not stderr.
139		if err := logging.Init(ctx, sessionID); err != nil {
140			// Init failed — logging will use stderr fallback, non-fatal.
141			_ = err
142		}
143	
144		logCtx := logging.WithComponent(ctx, "attach")
145	
146		// Open repository once — shared across all operations.
147		repo, err := openRepository(ctx)
148		if err != nil {
149			return err
150		}
151	
152		existingState, err := validateAttachPreconditions(ctx, repo, sessionID)
153		if err != nil {
154			return err
155		}
156	
157		headCommit, err := getHeadCommit(repo)
158		if err != nil {
159			return err
160		}
161	
162		// If session already has a checkpoint, just offer to link it.
163		if existingState != nil && !existingState.LastCheckpointID.IsEmpty() {
164			// Review-upgrade isn't supported yet: the existing checkpoint's
165			// metadata tree would need to be rewritten with Kind/ReviewSkills/
166			// ReviewPrompt set, and a new commit pushed onto entire/checkpoints/v1.
167			// Error out with a concrete message rather than silently linking the
168			// checkpoint without the review metadata.
169			if opts.Review {
170				return fmt.Errorf(
171					"session %s already has checkpoint %s; rewriting an existing checkpoint as a review is not supported yet",
172					sessionID, existingState.LastCheckpointID.String(),
173				)
174			}
175			cpID := existingState.LastCheckpointID.String()
176			fmt.Fprintf(w, "Session %s already has checkpoint %s\n", sessionID, cpID)
177			if err := promptAmendCommit(logCtx, w, headCommit, cpID, opts.Force); err != nil {
178				logging.Warn(logCtx, "failed to amend commit", "error", err)
179				fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", cpID)
180			}
181			return nil
182		}
183	
184		// Resolve agent and transcript path.
185		ag, transcriptPath, err := resolveAgentAndTranscript(logCtx, w, sessionID, agentName, existingState)
186		if err != nil {
187			return err
188		}
189	
190		var reviewSkills []string
191		if opts.Review {
192			reviewSkills = resolveReviewSkills(opts.ReviewSkillsOverride)
193		}
194	
195		transcriptData, err := ag.ReadTranscript(transcriptPath)
196		if err != nil {
197			return fmt.Errorf("failed to read transcript: %w", err)
198		}
199	
200		// Normalize Gemini transcripts for storage.
201		storedTranscript := transcriptData
202		if ag.Type() == agent.AgentTypeGemini {
203			if normalized, normErr := geminicli.NormalizeTranscript(transcriptData); normErr == nil {
204				storedTranscript = normalized
205			} else {
206				logging.Warn(logCtx, "failed to normalize Gemini transcript, storing raw", "error", normErr)
207			}
208		}
209	
210		meta := extractTranscriptMetadata(transcriptData)
211	
212		// Determine checkpoint ID: reuse from HEAD if one exists, otherwise generate new.
213		checkpointID, isExistingCheckpoint := resolveCheckpointID(headCommit)
214	
215		// Write directly to entire/checkpoints/v1.
216		store := cpkg.NewGitStore(repo)
217	
218		author, err := GetGitAuthor(ctx)
219		if err != nil {
220			return fmt.Errorf("failed to get git author: %w", err)
221		}
222	
223		var prompts []string
224		if meta.FirstPrompt != "" {
225			prompts = []string{meta.FirstPrompt}
226		}
227	
228		tokenUsage := agent.CalculateTokenUsage(logCtx, ag, transcriptData, 0, "")
229	
230		_, redactSpan := perf.Start(ctx, "redact_transcript")
231		redactedTranscript, redactErr := redact.JSONLBytes(storedTranscript)
232		redactSpan.End()
233		if redactErr != nil {
234			return fmt.Errorf("failed to redact transcript: %w", redactErr)
235		}
236	
237		writeOpts := cpkg.WriteCommittedOptions{
238			CheckpointID: checkpointID,
239			SessionID:    sessionID,
240			Strategy:     strategy.StrategyNameManualCommit,
241			Transcript:   redactedTranscript,
242			Prompts:      prompts,
243			AuthorName:   author.Name,
244			AuthorEmail:  author.Email,
245			Agent:        ag.Type(),
246			Model:        meta.Model,
247			TokenUsage:   tokenUsage,
248		}
249		if opts.Review {
250			writeOpts.Kind = string(session.KindAgentReview)
251			writeOpts.ReviewSkills = reviewSkills
252			writeOpts.ReviewPrompt = meta.FirstPrompt
253			writeOpts.HasReview = true
254		}
255	
256		if compacted := compactTranscriptForStartLine(logCtx, redactedTranscript.Bytes(), cpkg.CommittedMetadata{
257			CheckpointID: checkpointID,
258			Agent:        ag.Type(),
259		}, 0); compacted != nil {
260			writeOpts.CompactTranscript = compacted
261		}
262	
263		v2 := settings.CheckpointsVersion(logCtx) == 2
264		if !v2 {
265			if err := store.WriteCommitted(ctx, writeOpts); err != nil {
266				return fmt.Errorf("failed to write checkpoint: %w", err)
267			}
268		}
269		// IsCheckpointsV2Enabled is true whenever v2 writes are enabled, including
270		// both v2-only mode (checkpoints_version == 2) and dual-write mode. Only
271		// v2-only mode propagates the error.
272		if settings.IsCheckpointsV2Enabled(logCtx) {
273			if err := writeAttachCheckpointV2(logCtx, repo, writeOpts); err != nil {
274				if v2 {
275					return fmt.Errorf("failed to write checkpoint to v2: %w", err)
276				}
277				logging.Warn(logCtx, "attach v2 dual-write failed", "error", err)
278			}
279		}
280	
281		// Create or update session state.
282		if err := saveAttachSessionState(logCtx, existingState, sessionID, ag.Type(), transcriptPath, checkpointID, meta, tokenUsage, opts, reviewSkills); err != nil {
283			logging.Warn(logCtx, "failed to save session state", "error", err)
284		}
285	
286		fmt.Fprintf(w, "Attached session %s\n", sessionID)
287		if isExistingCheckpoint {
288			fmt.Fprintf(w, "  Added to existing checkpoint %s\n", checkpointID)
289			return nil
290		}
291	
292		fmt.Fprintf(w, "  Created checkpoint %s\n", checkpointID)
293		cpIDStr := checkpointID.String()
294		if err := promptAmendCommit(logCtx, w, headCommit, cpIDStr, opts.Force); err != nil {
295			logging.Warn(logCtx, "failed to amend commit", "error", err)
296			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", cpIDStr)
297		}
298	
299		return nil
300	}
