317	// getHeadCommit returns the HEAD commit object.
318	func getHeadCommit(repo *git.Repository) (*object.Commit, error) {
319		headRef, err := repo.Head()
320		if err != nil {
321			return nil, fmt.Errorf("failed to get HEAD: %w", err)
322		}
323		commit, err := repo.CommitObject(headRef.Hash())
324		if err != nil {
325			return nil, fmt.Errorf("failed to get HEAD commit: %w", err)
326		}
327		return commit, nil
328	}
