330	// resolveCheckpointID returns the checkpoint ID to use for the attach.
331	// If HEAD already has an Entire-Checkpoint trailer, reuses that ID (the session
332	// gets added as an additional session in the existing checkpoint).
333	// Otherwise generates a new ID.
334	func resolveCheckpointID(headCommit *object.Commit) (id.CheckpointID, bool) {
335		existing := trailers.ParseAllCheckpoints(headCommit.Message)
336		if len(existing) > 0 {
337			return existing[len(existing)-1], true
338		}
339	
340		cpID, err := id.Generate()
341		if err != nil {
342			// Generation only fails if crypto/rand fails — extremely unlikely.
343			// Fall back to empty which will cause WriteCommitted to fail with a clear error.
344			return id.EmptyCheckpointID, false
345		}
346		return cpID, false
347	}
