349	// saveAttachSessionState creates or updates the session state file for the attached session.
350	// If existingState is non-nil, it is updated in place (avoids a redundant disk load).
351	// reviewSkills is the resolved skills list when opts.Review is true; ignored otherwise.
352	func saveAttachSessionState(ctx context.Context, existingState *session.State, sessionID string, agentType types.AgentType, transcriptPath string, checkpointID id.CheckpointID, meta transcriptMetadata, tokenUsage *agent.TokenUsage, opts attachOptions, reviewSkills []string) error {
353		stateStore, err := session.NewStateStore(ctx)
354		if err != nil {
355			return fmt.Errorf("failed to open session store: %w", err)
356		}
357	
358		now := time.Now()
359		state := existingState
360		if state == nil {
361			state = &session.State{
362				SessionID: sessionID,
363				StartedAt: now,
364			}
365		}
366	
367		state.CLIVersion = versioninfo.Version
368		state.AttachedManually = true
369		state.AgentType = agentType
370		state.TranscriptPath = transcriptPath
371		state.LastCheckpointID = checkpointID
372		state.Phase = session.PhaseEnded
373		state.LastInteractionTime = &now
374		if meta.TurnCount > 0 {
375			state.SessionTurnCount = meta.TurnCount
376		}
377		if meta.Model != "" {
378			state.ModelName = meta.Model
379		}
380		if meta.FirstPrompt != "" {
381			state.LastPrompt = meta.FirstPrompt
382		}
383		if tokenUsage != nil {
384			state.TokenUsage = tokenUsage
385		}
386		if opts.Review {
387			state.Kind = session.KindAgentReview
388			state.ReviewSkills = reviewSkills
389			state.ReviewPrompt = meta.FirstPrompt
390		}
391	
392		if err := stateStore.Save(ctx, state); err != nil {
393			return fmt.Errorf("failed to save session state: %w", err)
394		}
395		return nil
396	}
