398	// validateAttachPreconditions checks session ID format and git repo state.
399	// Returns the existing session state if the session is already tracked (nil if new).
400	func validateAttachPreconditions(ctx context.Context, repo *git.Repository, sessionID string) (*session.State, error) {
401		if err := validation.ValidateSessionID(sessionID); err != nil {
402			return nil, fmt.Errorf("invalid session ID: %w", err)
403		}
404	
405		if strategy.IsEmptyRepository(repo) {
406			return nil, errors.New("repository has no commits yet — make an initial commit before running attach")
407		}
408	
409		store, err := session.NewStateStore(ctx)
410		if err != nil {
411			return nil, fmt.Errorf("failed to open session store: %w", err)
412		}
413		existing, err := store.Load(ctx, sessionID)
414		if err != nil {
415			return nil, fmt.Errorf("failed to check existing session: %w", err)
416		}
417	
418		return existing, nil
419	}
