463	// resolveAndValidateTranscript finds the transcript file for a session, searching alternative
464	// project directories if needed.
465	func resolveAndValidateTranscript(ctx context.Context, sessionID string, ag agent.Agent) (string, error) {
466		transcriptPath, err := resolveTranscriptPath(ctx, sessionID, ag)
467		if err != nil {
468			return "", fmt.Errorf("failed to resolve transcript path: %w", err)
469		}
470		// Only call PrepareTranscript when the file already exists — it flushes
471		// in-progress writes, but can't conjure a file that was never started.
472		// This avoids agents like Cursor polling for 3s on non-existent files
473		// during auto-detection.
474		if _, statErr := os.Stat(transcriptPath); statErr == nil {
475			if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
476				if prepErr := preparer.PrepareTranscript(ctx, transcriptPath); prepErr != nil {
477					logging.Debug(ctx, "PrepareTranscript failed (best-effort)", "error", prepErr)
478				}
479			}
480			return transcriptPath, nil
481		}
482		found, searchErr := searchTranscriptInProjectDirs(sessionID, ag)
483		if searchErr == nil {
484			logging.Info(ctx, "found transcript in alternative project directory", "path", found)
485			return found, nil
486		}
487		logging.Debug(ctx, "fallback transcript search failed", "error", searchErr)
488		return "", fmt.Errorf("transcript not found for agent %q with session %s; is the session ID correct?", ag.Name(), sessionID)
489	}
490	
491	// detectAgentByTranscript tries all registered agents (except skip) to find one whose
492	// transcript resolution succeeds for the given session ID.
493	func detectAgentByTranscript(ctx context.Context, sessionID string, skip types.AgentName) (agent.Agent, string, error) {
494		for _, name := range agent.List() {
495			if name == skip {
496				continue
497			}
498			ag, err := agent.Get(name)
499			if err != nil {
500				continue
501			}
502			path, resolveErr := resolveAndValidateTranscript(ctx, sessionID, ag)
503			if resolveErr != nil {
504				logging.Debug(ctx, "auto-detect: agent did not match", "agent", string(name), "error", resolveErr)
505				continue
506			}
507			return ag, path, nil
508		}
509		return nil, "", errors.New("transcript not found for any registered agent")
510	}
