512	// promptAmendCommit shows the last commit and asks whether to amend it with the checkpoint trailer.
513	// When force is true, it amends without prompting.
514	func promptAmendCommit(ctx context.Context, w io.Writer, headCommit *object.Commit, checkpointIDStr string, force bool) error {
515		shortHash := headCommit.Hash.String()[:7]
516		subject := strings.SplitN(headCommit.Message, "\n", 2)[0]
517	
518		// Skip amending if this exact checkpoint ID is already in the commit.
519		for _, existing := range trailers.ParseAllCheckpoints(headCommit.Message) {
520			if existing.String() == checkpointIDStr {
521				fmt.Fprintf(w, "Commit %s already has Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
522				return nil
523			}
524		}
525	
526		fmt.Fprintf(w, "\nLast commit: %s %s\n", shortHash, subject)
527	
528		amend := true
529		if !force {
530			if !interactive.CanPromptInteractively() {
531				// Non-interactive: can't prompt, print trailer for manual use.
532				fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
533				return nil
534			}
535			form := NewAccessibleForm(
536				huh.NewGroup(
537					huh.NewConfirm().
538						Title("Amend the last commit in this branch?").
539						Affirmative("Y").
540						Negative("n").
541						Value(&amend),
542				),
543			)
544			if err := form.Run(); err != nil {
545				return fmt.Errorf("prompt failed: %w", err)
546			}
547		}
548	
549		if !amend {
550			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
551			return nil
552		}
553	
554		newMessage := trailers.AppendCheckpointTrailer(headCommit.Message, checkpointIDStr)
555	
556		cmd := exec.CommandContext(ctx, "git", "commit", "--amend", "--only", "-m", newMessage)
557		if output, err := cmd.CombinedOutput(); err != nil {
558			return fmt.Errorf("failed to amend commit: %w\n%s", err, output)
559		}
560	
561		fmt.Fprintf(w, "Amended commit %s with Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
562		return nil
563	}
