63	// handleLifecycleSessionStart handles session start: shows banner, checks concurrent sessions,
64	// fires state machine transition.
65	func handleLifecycleSessionStart(ctx context.Context, ag agent.Agent, event *agent.Event) error {
66		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
67		logging.Info(logCtx, "session-start",
68			slog.String("event", event.Type.String()),
69			slog.String("session_id", event.SessionID),
70			slog.String("session_ref", event.SessionRef),
71			slog.String("model", event.Model),
72		)
73	
74		if event.SessionID == "" {
75			return fmt.Errorf("no session_id in %s event", event.Type)
76		}
77		if err := validation.ValidateSessionID(event.SessionID); err != nil {
78			return fmt.Errorf("invalid %s event: %w", event.Type, err)
79		}
80	
81		// Build informational message — warn early if repo has no commits yet,
82		// since checkpoints require at least one commit to work.
83		message := sessionStartMessage(ag.Name(), false)
84		if repo, err := strategy.OpenRepository(ctx); err == nil && strategy.IsEmptyRepository(repo) {
85			message = sessionStartMessage(ag.Name(), true)
86		}
87	
88		// Check for concurrent sessions and append count if any
89		_, countSessionsSpan := perf.Start(ctx, "count_active_sessions")
90		strat := GetStrategy(ctx)
91		if count, err := strat.CountOtherActiveSessionsWithCheckpoints(ctx, event.SessionID); err == nil && count > 0 {
92			if ag.Name() == agent.AgentNameCodex {
93				message += fmt.Sprintf(" %d other active conversation(s) in this workspace will also be included. Use 'entire status' for more information.", count)
94			} else {
95				message += fmt.Sprintf("\n  %d other active conversation(s) in this workspace will also be included.\n  Use 'entire status' for more information.", count)
96			}
97		}
98		countSessionsSpan.End()
99	
100		// Output informational message if the agent supports hook responses.
101		// Claude Code reads JSON from stdout; agents that don't implement
102		// HookResponseWriter silently skip (avoids raw JSON in their terminal).
103		_, hookResponseSpan := perf.Start(ctx, "write_hook_response")
104		if event.ResponseMessage != "" {
105			message = event.ResponseMessage
106		}
107		if writer, ok := agent.AsHookResponseWriter(ag); ok {
108			if err := writer.WriteHookResponse(message); err != nil {
109				hookResponseSpan.RecordError(err)
110				hookResponseSpan.End()
111				return fmt.Errorf("failed to write hook response: %w", err)
112			}
113		}
114		hookResponseSpan.End()
115	
116		// Store model hint if the agent provided model info on SessionStart
117		if event.Model != "" {
118			if err := strategy.StoreModelHint(ctx, event.SessionID, event.Model); err != nil {
119				logging.Warn(logCtx, "failed to store model hint on session start",
120					slog.String("error", err.Error()))
121			}
122		}
123	
124		// Fire EventSessionStart for the current session (if state exists).
125		if state, loadErr := strategy.LoadSessionState(ctx, event.SessionID); loadErr != nil {
126			logging.Warn(logCtx, "failed to load session state on start",
127				slog.String("error", loadErr.Error()))
128		} else if state != nil {
129			persistEventMetadataToState(event, state)
130			if transErr := strategy.TransitionAndLog(ctx, state, session.EventSessionStart, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
131				logging.Warn(logCtx, "session start transition failed",
132					slog.String("error", transErr.Error()))
133			}
134			if saveErr := strategy.SaveSessionState(ctx, state); saveErr != nil {
135				logging.Warn(logCtx, "failed to update session state on start",
136					slog.String("error", saveErr.Error()))
137			}
138		}
139	
140		return nil
141	}
142	
143	func sessionStartMessage(agentName types.AgentName, emptyRepo bool) string {
144		if agentName == agent.AgentNameCodex {
145			if emptyRepo {
146				return "Entire CLI found no commits yet — checkpoints will activate after your first commit."
147			}
148			return "Entire CLI will link this conversation to your next commit."
149		}
150	
151		if emptyRepo {
152			return "\n\nEntire CLI found no commits yet — checkpoints will activate after your first commit."
153		}
154		return "\n\nEntire CLI will link this conversation to your next commit."
155	}
