20	// installHooksForTest installs the given agent's hooks into CWD-relative
21	// repo paths, so tests that exercise code paths gated on hook presence can
22	// proceed past agent selection.
23	func installHooksForTest(t *testing.T, agentName types.AgentName) {
24		t.Helper()
25		ag, err := agent.Get(agentName)
26		if err != nil {
27			t.Fatalf("agent.Get(%q): %v", agentName, err)
28		}
29		hs, ok := agent.AsHookSupport(ag)
30		if !ok {
31			t.Fatalf("agent %q does not support hooks", agentName)
32		}
33		if _, err := hs.InstallHooks(context.Background(), false, false); err != nil {
34			t.Fatalf("InstallHooks(%q): %v", agentName, err)
35		}
36	}
