63	
64		m := PendingReviewMarker{
65			AgentName:   "claude-code",
66			Skills:      []string{testReviewSkill},
67			Prompt:      "Please run these review skills in order:\n  1. " + testReviewSkill + "\n",
68			StartingSHA: "deadbeef",
69			StartedAt:   time.Now().UTC(),
70		}
71		ctx := context.Background()
72		if err := WritePendingReviewMarker(ctx, m); err != nil {
73			t.Fatalf("write: %v", err)
74		}
75		got, ok, err := ReadPendingReviewMarker(ctx)
76		if err != nil {
77			t.Fatalf("read: %v", err)
78		}
79		if !ok {
80			t.Fatal("expected marker present")
81		}
82		if got.AgentName != m.AgentName || got.StartingSHA != m.StartingSHA {
83			t.Errorf("roundtrip mismatch: %+v", got)
84		}
85		if got.Prompt != m.Prompt {
86			t.Errorf("Prompt roundtrip mismatch: got %q want %q", got.Prompt, m.Prompt)
87		}
88	
89		// Marker file must live under .git/entire-sessions/, not the worktree.
90		// Check before clearing so the file is actually present on disk.
91		markerGlob := filepath.Join(tmp, ".git", "entire-sessions", "*")
92		entries, err := filepath.Glob(markerGlob)
93		if err != nil {
94			t.Fatalf("glob sessions dir: %v", err)
95		}
96		if len(entries) == 0 {
97			t.Errorf("no marker file found under %s — path resolution may have regressed", markerGlob)
98		}
99	
100		if err := ClearPendingReviewMarker(ctx); err != nil {
101			t.Fatalf("clear: %v", err)
102		}
103		_, ok, err = ReadPendingReviewMarker(ctx)
104		if err != nil {
105			t.Fatalf("read-after-clear: %v", err)
106		}
107		if ok {
108			t.Error("expected marker absent after clear")
109		}
110	}
