313	// mergePickerResults unit tests — the picker itself can't run headless, but
314	// its post-processing step is pure. Together these pin the data-loss
315	// regression where a manually-configured external-agent entry would be
316	// silently deleted the first time the user ran `entire review --edit`.
317	func TestMergePickerResults(t *testing.T) {
318		t.Parallel()
319		tests := []struct {
320			name     string
321			existing map[string]settings.ReviewConfig
322			offered  map[string]struct{}
323			selected map[string]settings.ReviewConfig
324			want     map[string]settings.ReviewConfig
325		}{
326			{
327				name: "preserves uncurated/external entries the picker did not surface",
328				existing: map[string]settings.ReviewConfig{
329					testAgentName:     {Skills: []string{"/old-pick"}},
330					testExternalAgent: {Skills: []string{testExternalSkill}},
331				},
332				offered:  map[string]struct{}{testAgentName: {}},
333				selected: map[string]settings.ReviewConfig{testAgentName: {Skills: []string{"/new-pick"}}},
334				want: map[string]settings.ReviewConfig{
335					testAgentName:     {Skills: []string{"/new-pick"}},
336					testExternalAgent: {Skills: []string{testExternalSkill}}, // MUST survive
337				},
338			},
339			{
340				name: "offered agent with no picks is removed (user unconfiguring)",
341				existing: map[string]settings.ReviewConfig{
342					testAgentName:  {Skills: []string{"/old-pick"}},
343					testCodexAgent: {Skills: []string{"/codex-pick"}},
344				},
345				offered:  map[string]struct{}{testAgentName: {}, testCodexAgent: {}},
346				selected: map[string]settings.ReviewConfig{testAgentName: {Skills: []string{"/new-pick"}}},
347				want: map[string]settings.ReviewConfig{
348					testAgentName: {Skills: []string{"/new-pick"}},
349				},
350			},
351			{
352				name:     "empty existing: merge is identity on selected",
353				existing: map[string]settings.ReviewConfig{},
354				offered:  map[string]struct{}{testAgentName: {}},
355				selected: map[string]settings.ReviewConfig{testAgentName: {Skills: []string{"/a"}}},
356				want:     map[string]settings.ReviewConfig{testAgentName: {Skills: []string{"/a"}}},
357			},
358			{
359				// Regression: deselecting all curated agents while external
360				// config remains must yield a non-empty merged map, so --edit
361				// can save the "only external agent left" state.
362				name: "deselected curated agent leaves only external entry",
363				existing: map[string]settings.ReviewConfig{
364					testAgentName:     {Skills: []string{"/old-pick"}},
365					testExternalAgent: {Skills: []string{testExternalSkill}},
366				},
367				offered:  map[string]struct{}{testAgentName: {}},
368				selected: map[string]settings.ReviewConfig{}, // user deselected everything offered
369				want: map[string]settings.ReviewConfig{
370					testExternalAgent: {Skills: []string{testExternalSkill}},
371				},
372			},
373			{
374				// A custom prompt without skills is a valid, non-zero entry.
375				// Users can configure a freeform review with no skills list.
376				name:     "prompt-only entry is preserved",
377				existing: map[string]settings.ReviewConfig{},
378				offered:  map[string]struct{}{testAgentName: {}},
379				selected: map[string]settings.ReviewConfig{
380					testAgentName: {Prompt: "Focus on security regressions."},
381				},
382				want: map[string]settings.ReviewConfig{
383					testAgentName: {Prompt: "Focus on security regressions."},
384				},
385			},
386		}
387		for _, tc := range tests {
388			t.Run(tc.name, func(t *testing.T) {
389				t.Parallel()
390				got := mergePickerResults(tc.existing, tc.offered, tc.selected)
391				if !reflect.DeepEqual(got, tc.want) {
392					t.Errorf("mergePickerResults =\n  %v\nwant\n  %v", got, tc.want)
393				}
394			})
395		}
396	}
