23	func TestReview_MarkerAdoptionCondensesReviewMetadataOnNextCommit(t *testing.T) {
24		t.Parallel()
25	
26		env := NewFeatureBranchEnv(t)
27		enableReviewAgent(t, env, "claude-code")
28	
29		env.WritePendingReviewMarker(
30			"claude-code",
31			[]string{"/pr-review-toolkit:review-pr", "/test-auditor"},
32			env.GetHeadHash(),
33		)
34	
35		sess := env.NewSession()
36		reviewPrompt := "review the branch for correctness and missing tests"
37		if err := env.SimulateUserPromptSubmitWithPrompt(sess.ID, reviewPrompt); err != nil {
38			t.Fatalf("SimulateUserPromptSubmitWithPrompt failed: %v", err)
39		}
40	
41		state, err := env.GetSessionState(sess.ID)
42		if err != nil {
43			t.Fatalf("GetSessionState failed: %v", err)
44		}
45		if state == nil {
46			t.Fatal("expected review session state to be created")
47		}
48		if state.Kind != session.KindAgentReview {
49			t.Fatalf("state.Kind = %q, want %q", state.Kind, session.KindAgentReview)
50		}
51		if len(state.ReviewSkills) != 2 || state.ReviewSkills[0] != "/pr-review-toolkit:review-pr" || state.ReviewSkills[1] != "/test-auditor" {
52			t.Fatalf("state.ReviewSkills = %v", state.ReviewSkills)
53		}
54		if !strings.Contains(state.ReviewPrompt, "/pr-review-toolkit:review-pr") || !strings.Contains(state.ReviewPrompt, "/test-auditor") {
55			t.Fatalf("state.ReviewPrompt missing configured skills: %q", state.ReviewPrompt)
56		}
57	
58		env.WriteFile("review_target.go", "package main\n\nfunc ReviewTarget() string { return \"ok\" }\n")
59		sess.CreateTranscript(reviewPrompt, []FileChange{
60			{Path: "review_target.go", Content: "package main\n\nfunc ReviewTarget() string { return \"ok\" }\n"},
61		})
62		if err := env.SimulateStop(sess.ID, sess.TranscriptPath); err != nil {
63			t.Fatalf("SimulateStop failed: %v", err)
64		}
65	
66		env.GitCommitWithShadowHooks("add review target", "review_target.go")
67	
68		checkpointID := env.GetCheckpointIDFromCommitMessage(env.GetHeadHash())
69		if checkpointID == "" {
70			t.Fatal("expected Entire-Checkpoint trailer on HEAD after commit")
71		}
72	
73		summary := readCheckpointSummary(t, env, checkpointID)
74		if !summary.HasReview {
75			t.Fatalf("summary.HasReview = false for checkpoint %s", checkpointID)
76		}
77	
78		metadata := readSessionMetadata(t, env, checkpointID)
79		if metadata.SessionID != sess.ID {
80			t.Fatalf("metadata.SessionID = %q, want %q", metadata.SessionID, sess.ID)
81		}
82		if metadata.Kind != string(session.KindAgentReview) {
83			t.Fatalf("metadata.Kind = %q, want %q", metadata.Kind, session.KindAgentReview)
84		}
85		if len(metadata.ReviewSkills) != 2 || metadata.ReviewSkills[0] != "/pr-review-toolkit:review-pr" || metadata.ReviewSkills[1] != "/test-auditor" {
86			t.Fatalf("metadata.ReviewSkills = %v", metadata.ReviewSkills)
87		}
88		if metadata.ReviewPrompt != state.ReviewPrompt {
89			t.Fatalf("metadata.ReviewPrompt = %q, want %q", metadata.ReviewPrompt, state.ReviewPrompt)
90		}
91	}
